class Task {

    private static int mod = 998244353;

    public void solve(int n, long k, PrintWriter out) {
        long[] fac = new long[200001];
        long[] inv = new long[200001];
        fac[0] = inv[0] = 1;
        for (int i = 1; i < 200001; i++) {
            fac[i] = fac[i - 1] * i % mod;
            inv[i] = inv[i - 1] * powMod(i, mod - 2) % mod;
        }
        if (k >= n) {
            out.println(0);
            return;
        }
        if (k == 0) {
            out.println(fac[n]);
            return;
        }
        int m = (int)(n - k);
        long ans = 0;
        for (int i = 0; i <= m; i++) {
            if (i % 2 == 0) {
                ans = (ans + getC(fac, inv, m, i) * powMod(m - i, n) % mod) % mod;
            } else {
                ans = ((ans - getC(fac, inv, m, i) * powMod(m - i, n) % mod) + mod) % mod;
            }
        }
        long result = 2 * fac[n] % mod * inv[n - m] % mod * ans % mod * inv[m] % mod;
        out.println(result);
    }

    private long powMod(long a, long b) {
        long ans = 1, d = a;
        while (b > 0) {
            if ((b & 1) == 1) ans = ans * d % mod;
            b >>= 1;
            d = d * d % mod;
        }
        return ans;
    }

    private long getC(long[] fac, long[] inv, int n, int m) {
        return fac[n] * inv[m] % mod * inv[n - m] % mod;
    }
}
