#include <bits/stdc++.h>
using namespace std;

const int mod = 998244353;

long long powMod(long long a, long long b) {
    long long ans = 1, d = a;
    while (b > 0) {
        if (b & 1) ans = ans * d % mod;
        b >>= 1;
        d = d * d % mod;
    }
    return ans;
}

long long getC(const vector<long long>& fac, const vector<long long>& inv, int n, int m) {
    return fac[n] * inv[m] % mod * inv[n - m] % mod;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long k;
    cin >> n >> k;

    vector<long long> fac(200001);
    vector<long long> inv(200001);
    fac[0] = inv[0] = 1;
    for (int i = 1; i < 200001; i++) {
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = inv[i - 1] * powMod(i, mod - 2) % mod;
    }

    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }
    if (k == 0) {
        cout << fac[n] << "\n";
        return 0;
    }

    int m = (int)(n - k);
    long long ans = 0;
    for (int i = 0; i <= m; i++) {
        long long c = getC(fac, inv, m, i);
        long long val = powMod(m - i, n);
        if (i % 2 == 0) {
            ans = (ans + c * val % mod) % mod;
        } else {
            ans = (ans - c * val % mod + mod) % mod;
        }
    }

    long long result = 2LL * fac[n] % mod * inv[n - m] % mod * ans % mod * inv[m] % mod;
    cout << result << "\n";

    return 0;
}
